-- Reverse migration 000015: remove binding tools, new skills, and bindings.

-- Remove agent_skill bindings for new skills on AgentHub Assistant.
DELETE FROM agent_skill WHERE agent_id = 'd1000000-0000-0000-0001-000000000001'
  AND skill_id IN ('b1000000-0000-0000-0000-000000000009', 'b1000000-0000-0000-0000-000000000010');

-- Remove skill_tool bindings for new tools.
DELETE FROM skill_tool WHERE tool_id IN (
    'c1000000-0000-0000-0000-000000000032',
    'c1000000-0000-0000-0000-000000000033',
    'c1000000-0000-0000-0000-000000000034',
    'c1000000-0000-0000-0000-000000000035',
    'c1000000-0000-0000-0000-000000000036',
    'c1000000-0000-0000-0000-000000000037',
    'c1000000-0000-0000-0000-000000000038',
    'c1000000-0000-0000-0000-000000000039',
    'c1000000-0000-0000-0000-000000000040'
);

-- Remove new tools.
DELETE FROM tool WHERE id IN (
    'c1000000-0000-0000-0000-000000000032',
    'c1000000-0000-0000-0000-000000000033',
    'c1000000-0000-0000-0000-000000000034',
    'c1000000-0000-0000-0000-000000000035',
    'c1000000-0000-0000-0000-000000000036',
    'c1000000-0000-0000-0000-000000000037',
    'c1000000-0000-0000-0000-000000000038',
    'c1000000-0000-0000-0000-000000000039',
    'c1000000-0000-0000-0000-000000000040'
);

-- Remove new skills.
DELETE FROM skill WHERE id IN (
    'b1000000-0000-0000-0000-000000000007',
    'b1000000-0000-0000-0000-000000000008',
    'b1000000-0000-0000-0000-000000000009',
    'b1000000-0000-0000-0000-000000000010'
